Primary.parameters = {
  ...Primary.parameters,
  docs: {
    ...Primary.parameters?.docs,
    source: {
      originalSource: "{\n  tags: ['sidebar-ignore'],\n  render: args => <StoryStack height=\"35vh\" backgroundColor={args.theme === 'dark' ? 'black' : undefined} padding={args.theme === 'dark' ? '2' : undefined}>\n      <Combobox {...args} placeholder=\"Some placeholder\">\n        {peopleList.map(({\n        name\n      }) => <ComboboxOption key={name} value={name}>\n            <ComboboxOptionLabel>{name}</ComboboxOptionLabel>\n          </ComboboxOption>)}\n      </Combobox>\n    </StoryStack>,\n  play: async ({\n    canvasElement\n  }) => {\n    const {\n      canvas,\n      trigger,\n      clearButton,\n      items\n    } = await getElements(canvasElement);\n    const getInputElement = () => trigger.getElementsByTagName('input')[0];\n    await openDropdown(trigger);\n    await takeScreenshot?.();\n    await it('should select a value', async () => {\n      const listItems = await items();\n      await selectItemByClick(listItems[4]);\n      await expect(getInputElement().value).toBe(listItems[4].textContent);\n    });\n    await it('should not filter items after selecting an item and reopening the dropdown', async () => {\n      const listItems = await items();\n      await openDropdown(trigger);\n      await expect((await canvas.findByRole('list')).childElementCount).toBe(listItems.length);\n    });\n    await it('should filter items after selecting an element and starting to type', async () => {\n      await keyboardEvent('[Space]');\n      await takeScreenshot?.();\n    });\n    await it('should delete letters from the input', async () => {\n      await keyboardEvent('[Backspace]', 3);\n      await takeScreenshot?.();\n    });\n    await it('should select the input text and delete it', async () => {\n      getInputElement().select();\n      await keyboardEvent('[Backspace]');\n    });\n    await it('should select a value', async () => {\n      const listItems = await items();\n      await selectItemByClick(listItems[3]);\n      await expect(getInputElement().value).toBe(listItems[3].textContent);\n    });\n    await it('Should clear selected items', async () => {\n      await clickElement(clearButton as Element);\n    });\n    await it('should test typing after clearing the input and verify if items are filtered', async () => {\n      await keyboardEvent('a', 1, {\n        delay: 400\n      });\n      await takeScreenshot?.();\n    });\n  }\n}",
      ...Primary.parameters?.docs?.source
    }
  }
};
MultiSelect.parameters = {
  ...MultiSelect.parameters,
  docs: {
    ...MultiSelect.parameters?.docs,
    source: {
      originalSource: "{\n  tags: ['sidebar-ignore', 'snapshot-ignore'],\n  render: args => <StoryStack height=\"35vh\">\n      <Combobox {...args}>\n        <ComboboxOptionGroup name=\"groupA\" isMulti>\n          {countries.map(({\n          name,\n          value\n        }) => <ComboboxOption key={value} value={value}>\n              <ComboboxOptionLabel>{name}</ComboboxOptionLabel>\n            </ComboboxOption>)}\n        </ComboboxOptionGroup>\n      </Combobox>\n    </StoryStack>,\n  play: async ({\n    canvasElement\n  }) => {\n    const {\n      trigger,\n      clearButton,\n      items,\n      canvas\n    } = await getElements(canvasElement);\n    await openDropdown(trigger);\n    await takeScreenshot?.();\n    await it('should select items using keyboard and click', async () => {\n      const listItems = await items();\n      await selectItemByClick(listItems[0]);\n      await selectItemByKeyboard('[ArrowDown]', 3);\n      await keyboardEvent('[ArrowDown]', 5);\n      await selectItemByKeyboard('[ArrowUp]');\n      await selectItemByKeyboard('[ArrowDown]');\n      await selectItemByKeyboard('[ArrowDown]');\n      await takeScreenshot?.();\n    });\n    await it('should test typing in input when there are selected items', async () => {\n      await keyboardEvent('c');\n      await takeScreenshot?.();\n    });\n    await it('should delete a letter from input', async () => {\n      await keyboardEvent('[Backspace]');\n      await takeScreenshot?.();\n    });\n    await it('should clear selected value tags', async () => {\n      await clickElement(clearButton as Element, {\n        delay: 300\n      });\n      await takeScreenshot?.();\n    });\n    await it('should select all items and display \"no more options\" text and focus tag', async () => {\n      const listItems = await items();\n      await selectItemByKeyboard('[ArrowDown]', 1, listItems.length);\n      await openDropdown(trigger);\n      await expect(await canvas.findByText('No more options')).toBeInTheDocument();\n    });\n    await it('should focus tag', async () => {\n      await keyboardEvent('[ArrowLeft]', 5);\n      await takeScreenshot?.(300);\n    });\n    await it('should lose focus on tag, focus input, and remove the last selected item', async () => {\n      await userEvent.tab();\n      await keyboardEvent('[Backspace]');\n      await openDropdown(trigger);\n      await takeScreenshot?.(200);\n    });\n    await it('should focus tag', async () => {\n      await keyboardEvent('[ArrowLeft]', 4);\n      await takeScreenshot?.(300);\n    });\n    await it('should delete focused tag and delete tag by click', async () => {\n      await keyboardEvent('[Backspace]');\n      const tag = Array.from(trigger.getElementsByTagName('button'))?.find(tag => tag.textContent === countries[5].name);\n      if (tag) {\n        await clickElement(tag);\n      }\n      await openDropdown(trigger);\n      await takeScreenshot?.(300);\n    });\n  }\n}",
      ...MultiSelect.parameters?.docs?.source
    }
  }
};
